(1119401, 137229, 20809, '<td valign="top">great shot.  would be better if the liquid(s) were coming from a plain glass pitcher or something - but you score well for trying something new (unlike most other entries) - 7.</td>', 'great shot.  would be better if the liquid(s) were coming from a plain glass pitcher or something - but you score well for trying something new (unlike most other entries) - 7.', '2005-01-19 14:42:50.000000', NULL, 1),
(1119405, 137449, 20809, '<td valign="top">good shot.  the long exposure creates a nice soft reflection on the pool.  -6</td>', 'good shot.  the long exposure creates a nice soft reflection on the pool.  -6', '2005-01-19 14:43:49.000000', NULL, 1),
(1119408, 137795, 22537, '<td valign="top">Great colors and a beautiful photo.  The corner composition os very effective.  Good luck!</td>', 'Great colors and a beautiful photo.  The corner composition os very effective.  Good luck!', '2005-01-19 14:44:47.000000', NULL, 1),
