INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1119411, 137722, 22537, '<td valign="top">Interesting perspective but does not grab me as very exciting.  Good luck!</td>', 'Interesting perspective but does not grab me as very exciting.  Good luck!', '2005-01-19 14:47:48.000000', NULL, 1),
(1119415, 137622, 22537, '<td valign="top">Wow!  A drunk teddy? With the oh so dry Pernod?  Interetsing social commentary, I think" but somewhat of a uninspiring composition.  Good luck.</td>', 'Wow!  A drunk teddy? With the oh so dry Pernod?  Interetsing social commentary, I think" but somewhat of a uninspiring composition.  Good luck.', '2005-01-19 14:49:37.000000', NULL, 1),
(1119416, 137595, 22537, '<td valign="top">Yes, a very literal interpretation but does not convey very much more than what is very apparent.  Good luck.</td>', 'Yes, a very literal interpretation but does not convey very much more than what is very apparent.  Good luck.', '2005-01-19 14:50:44.000000', NULL, 1),
(1119419, 135713, 22537, '<td valign="top">Very innovative especially if you are a dog lover.  Good luck.</td>', 'Very innovative especially if you are a dog lover.  Good luck.', '2005-01-19 14:51:41.000000', NULL, 1),
(1119424, 137817, 7252, '<td valign="top">Interesting technique but it doesn''t work here. This technique really only works when the axis of spin lands on a point of interest. For example if her eye was at the axis rather than the forehead this would be much better.</td>', 'Interesting technique but it doesn''t work here. This technique really only works when the axis of spin lands on a point of interest. For example if her eye was at the axis rather than the forehead this would be much better.', '2005-01-19 14:56:14.000000', NULL, 1),
(1119427, 137713, 22537, '<td valign="top">Firstly, this is a very clear and sharp image that is well balanced.  Good use of light and the tones are nice. I feel that the social commentary has thrown me off as a bit "in your face".  You have mixed praying and patriotism well but lack to show me how this is innovative.  Good luck.</td>', 'Firstly, this is a very clear and sharp image that is well balanced.  Good use of light and the tones are nice. I feel that the social commentary has thrown me off as a bit "in your face".  You have mixed praying and patriotism well but lack to show me how this is innovative.  Good luck.', '2005-01-19 14:58:10.000000', NULL, 1),
(1119428, 137820, 2716, '<td valign="top">The winner. 10  Jacko.  Very nicely done</td>', 'The winner. 10  Jacko.  Very nicely done', '2005-01-19 14:58:58.000000', NULL, 1),
(1119435, 137229, 7252, '<td valign="top">I think this image looks slightly better with a white background rather than a grey one. Very interesting effect. I look forward to reading about how you achieved the transition.</td>', 'I think this image looks slightly better with a white background rather than a grey one. Very interesting effect. I look forward to reading about how you achieved the transition.', '2005-01-19 15:02:11.000000', NULL, 1),
(1119442, 137789, 31443, '<td valign="top">I see light being absorbed but really nothing there...</td>', 'I see light being absorbed but really nothing there...', '2005-01-19 15:05:47.000000', NULL, 1),
(1119443, 137358, 22734, '<td valign="top">Now, here is a good technique  that would have done great in the impressionistic challenge.  Outside of the minor burnt out area, this is indeed a cool camera rattle rime exposure. The colots are great and the flying drumsticks add flavor. 7</td>', 'Now, here is a good technique  that would have done great in the impressionistic challenge.  Outside of the minor burnt out area, this is indeed a cool camera rattle rime exposure. The colots are great and the flying drumsticks add flavor. 7', '2005-01-19 15:08:10.000000', NULL, 1),
(1119444, 137748, 31443, '<td valign="top">Yes, this one I like a lot</td>', 'Yes, this one I like a lot', '2005-01-19 15:08:13.000000', NULL, 1),
(1119446, 137793, 22734, '<td valign="top">Interesting effect because the image splits into traditional rendition (the face) and then that poster look (the hand). very well done.</td>', 'Interesting effect because the image splits into traditional rendition (the face) and then that poster look (the hand). very well done.', '2005-01-19 15:10:53.000000', NULL, 1),
(1119449, 137712, 31443, '<td valign="top">Amazing how the color veins stick out in this image, like it</td>', 'Amazing how the color veins stick out in this image, like it', '2005-01-19 15:11:58.000000', NULL, 1),
(1119450, 137229, 7778, '<td valign="top">It has wit and a little humour, is sensibly and effectively composed and reveals no flagrant technical flaws. Unfortunately, this image relies almost entirely on the miracle of water-to-wine without conveying anything miraculous aesthetically. Its visual ambience remains cold and, perhaps, as dull as an illustration for a winery, drawn from a stock agency.<br/> <br/>I am rating this capture accordingly, while adding two points: one to compensate for the limits imposed with regards to editing by the Basic Challenge rules, another for the title. The title, to me, clearly places this photo into a known context, and it does this without, overtly, soliciting a favourable perspective.</td>', 'It has wit and a little humour, is sensibly and effectively composed and reveals no flagrant technical flaws. Unfortunately, this image relies almost entirely on the miracle of water-to-wine without conveying anything miraculous aesthetically. Its visual ambience remains cold and, perhaps, as dull as an illustration for a winery, drawn from a stock agency. I am rating this capture accordingly, while adding two points: one to compensate for the limits imposed with regards to editing by the Basic Challenge rules, another for the title. The title, to me, clearly places this photo into a known context, and it does this without, overtly, soliciting a favourable perspective.', '2005-01-19 15:12:04.000000', NULL, 1),
(1119451, 137515, 18403, '<td valign="top">The first image I have seen that meets the challenge.  10</td>', 'The first image I have seen that meets the challenge.  10', '2005-01-19 15:12:20.000000', NULL, 1),
(1119457, 137795, 31443, '<td valign="top">Lovely blooms</td>', 'Lovely blooms', '2005-01-19 15:14:05.000000', NULL, 1),
(1119458, 136288, 22734, '<td valign="top">Very nice. The way I would accomplish this, lacking d.e. is to use a single long exposure and shoot each position with a filter using strobe. Very well presented because it exceed the typical d.e. effect by adding the rbg charm. Bumping up</td>', 'Very nice. The way I would accomplish this, lacking d.e. is to use a single long exposure and shoot each position with a filter using strobe. Very well presented because it exceed the typical d.e. effect by adding the rbg charm. Bumping up', '2005-01-19 15:15:33.000000', NULL, 1),
(1119461, 136317, 31947, '<td valign="top">nice idea !</td>', 'nice idea !', '2005-01-19 15:17:35.000000', NULL, 1),
(1119464, 136230, 18403, '<td valign="top">Don''t know what is ''new ground'' here, but this is a very compelling image! 7</td>', 'Don''t know what is ''new ground'' here, but this is a very compelling image! 7', '2005-01-19 15:19:30.000000', NULL, 1),
