(1121932, 137082, 23394, '<td valign="top">i would find this more interesting if the focus was a bit sharper.  motion blur tends to be a lot more effective when the environment is absolutely dialed in.  nice effort though.  keep at it.</td>', 'i would find this more interesting if the focus was a bit sharper.  motion blur tends to be a lot more effective when the environment is absolutely dialed in.  nice effort though.  keep at it.', '2005-01-20 17:55:51.000000', NULL, 1),
(1121938, 135727, 23394, '<td valign="top">how sad is this.  i don''t know if i should score you out of sympathy for the dog or dock you for teasing her/him...</td>', 'how sad is this.  i don''t know if i should score you out of sympathy for the dog or dock you for teasing her/him...', '2005-01-20 17:57:32.000000', NULL, 1),
