(1123455, 137691, 14476, '<td valign="top">This is a fine image in many ways.  You handled the lighting well, and the composition is excellent with the leading lines all converging on the darker tree where the subtle curve bounces the viewer back into the picture again.   If this is a new venture for you, keep it up!  10</td>', 'This is a fine image in many ways.  You handled the lighting well, and the composition is excellent with the leading lines all converging on the darker tree where the subtle curve bounces the viewer back into the picture again.   If this is a new venture for you, keep it up!  10', '2005-01-21 13:22:54.000000', NULL, 1),
(1123459, 137795, 14476, '<td valign="top">Interesting.  As you say, no flowers for a long time, and I have two in my short list of 10s.  This is one of them.  Nice lighting and depth of field.</td>', 'Interesting.  As you say, no flowers for a long time, and I have two in my short list of 10s.  This is one of them.  Nice lighting and depth of field.', '2005-01-21 13:24:30.000000', NULL, 1),
