(1131611, 137389, 10275, '<td valign="top">Lovely golden tone, great sharpness. Nice triangular composition. The crop is a bit too tight though and the whole arrangement is too centered. Good attempt tough.</td>', 'Lovely golden tone, great sharpness. Nice triangular composition. The crop is a bit too tight though and the whole arrangement is too centered. Good attempt tough.', '2005-01-25 19:20:21.000000', NULL, 1),
(1131614, 137820, 10275, '<td valign="top">Very nice photo. Great colours on the main subject. A bit too tightly cropped at the top.</td>', 'Very nice photo. Great colours on the main subject. A bit too tightly cropped at the top.', '2005-01-25 19:21:25.000000', NULL, 1),
(1131617, 137668, 10275, '<td valign="top">Great snapshot. Nice colours and fogginess.</td>', 'Great snapshot. Nice colours and fogginess.', '2005-01-25 19:22:12.000000', NULL, 1),
