(1131764, 137518, 12268, '<td valign="top">sweet shot! 9</td>', 'sweet shot! 9', '2005-01-25 20:34:34.000000', NULL, 1),
(1131769, 137375, 12268, '<td valign="top">i like this shot. I think there is too much light in it tho. Perhaps a faster shutter speed, lower iso or larger ap. might have brought out more details in the overexposed part. Regradless, good stuff!</td>', 'i like this shot. I think there is too much light in it tho. Perhaps a faster shutter speed, lower iso or larger ap. might have brought out more details in the overexposed part. Regradless, good stuff!', '2005-01-25 20:37:20.000000', NULL, 1),
