(1132098, 137736, 30222, '<td valign="top">appealing and original</td>', 'appealing and original', '2005-01-25 23:31:02.000000', NULL, 1),
(1132099, 137389, 19943, '<td valign="top">I see too much contrast, red color and a strong shadow over the onions.  However, the focus is dead on, the subject is appropriate and I like the backdrop.</td>', 'I see too much contrast, red color and a strong shadow over the onions.  However, the focus is dead on, the subject is appropriate and I like the backdrop.', '2005-01-25 23:31:11.000000', NULL, 1),
(1132104, 137444, 19943, '<td valign="top">I really like the concept.  Perhaps a fill flash for the right side would have brought up the dead space a little.  The keys on the keyboard are at soft focus and the tops of the folders are too bright.  Spot metering a neutral area might have given you better settings for your camera.</td>', 'I really like the concept.  Perhaps a fill flash for the right side would have brought up the dead space a little.  The keys on the keyboard are at soft focus and the tops of the folders are too bright.  Spot metering a neutral area might have given you better settings for your camera.', '2005-01-25 23:34:49.000000', NULL, 1),
(1132105, 137463, 30222, '<td valign="top">great idea well executed</td>', 'great idea well executed', '2005-01-25 23:35:04.000000', NULL, 1),
(1132110, 137534, 19943, '<td valign="top">I love the colors and white out (snowed out in this case) background.  The muzzle is not focused enough; maybe it''s motion blur, but it needs to be tack on for this photo to work.</td>', 'I love the colors and white out (snowed out in this case) background.  The muzzle is not focused enough; maybe it''s motion blur, but it needs to be tack on for this photo to work.', '2005-01-25 23:36:26.000000', NULL, 1),
(1132113, 137463, 19943, '<td valign="top">great concept.  Maybe use sidelighting without a flash for better details.  Or, longer exposure with a fill flash to improve highlights (especially on the right eyebrow, eyelashes).</td>', 'great concept.  Maybe use sidelighting without a flash for better details.  Or, longer exposure with a fill flash to improve highlights (especially on the right eyebrow, eyelashes).', '2005-01-25 23:38:27.000000', NULL, 1),
