(1132159, 135658, 27375, '<td valign="top">I like it.</td>', 'I like it.', '2005-01-25 23:54:03.000000', NULL, 1),
(1132160, 136415, 17203, '<td valign="top">The blue eyes and harsh grain are distractions, but kudos for finding something new and creative! 8</td>', 'The blue eyes and harsh grain are distractions, but kudos for finding something new and creative! 8', '2005-01-25 23:54:07.000000', NULL, 1),
