(1132166, 135841, 27375, '<td valign="top">Cool!</td>', 'Cool!', '2005-01-25 23:55:40.000000', NULL, 1),
(1132169, 137229, 25355, '<td valign="top">I hope you''ll tell us how you did this - turning water into wine is not something many people can do. Well done.</td>', 'I hope you''ll tell us how you did this - turning water into wine is not something many people can do. Well done.', '2005-01-25 23:56:37.000000', NULL, 1),
(1132170, 137745, 17203, '<td valign="top">Nice sense of movement- I like the way that the entire surroundings have blurred away to silhouette the flower. Unfortunately, it looks like a lot of people took a motion blur approach, which could impact your score. 8</td>', 'Nice sense of movement- I like the way that the entire surroundings have blurred away to silhouette the flower. Unfortunately, it looks like a lot of people took a motion blur approach, which could impact your score. 8', '2005-01-25 23:57:47.000000', NULL, 1),
(1132173, 137229, 17203, '<td valign="top">This is just a stunning display of photographic prowess, and nothing short of magic. No way this shot scores under 7. Congratulations on your ribbon! 10</td>', 'This is just a stunning display of photographic prowess, and nothing short of magic. No way this shot scores under 7. Congratulations on your ribbon! 10', '2005-01-25 23:58:38.000000', NULL, 1),
