(1133035, 137712, 23394, '<td valign="top">SiSi, I''m sorry about the first comment I made on your image, as I don''t really think it was that helpful, especially considering the context of the challenge.  Sure, there are a number of things you could do differently from a technical standpoint to improve the image, but what you have done so far is not without merit.  I''m glad to see you improving, and as long as you keep trying, you''ll get where you want to be.</td>', 'SiSi, I''m sorry about the first comment I made on your image, as I don''t really think it was that helpful, especially considering the context of the challenge.  Sure, there are a number of things you could do differently from a technical standpoint to improve the image, but what you have done so far is not without merit.  I''m glad to see you improving, and as long as you keep trying, you''ll get where you want to be.', '2005-01-26 10:17:34.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
